use std::collections::HashMap;

use crate::{FieldMetadata, Raw, Table};

/// The schema a codebase declares, as `DEFINE` statements grouped by kind; migrations are
/// generated by comparing it with the schema the migration files produce.
///
/// Each statement is complete, ending with `;`, as statement builders render them.
pub trait DbResources {
    /// Table definitions, each followed by its fields, indexes and events.
    fn tables(&self) -> Vec<Raw> {
        vec![]
    }

    /// The fields of each table, with their previous names for renames.
    fn tables_fields_meta(&self) -> HashMap<Table, Vec<FieldMetadata>> {
        HashMap::default()
    }

    /// Analyzer definitions.
    fn analyzers(&self) -> Vec<Raw> {
        vec![]
    }

    /// Function definitions.
    fn functions(&self) -> Vec<Raw> {
        vec![]
    }

    /// Param definitions.
    fn params(&self) -> Vec<Raw> {
        vec![]
    }

    /// Database access definitions (`DEFINE ACCESS … ON DATABASE`).
    fn accesses(&self) -> Vec<Raw> {
        vec![]
    }

    /// Database user definitions (`DEFINE USER … ON DATABASE`).
    fn users(&self) -> Vec<Raw> {
        vec![]
    }
}
